ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'reading/arabic/b2/passages.jsonl';LEX=ROOT/'reading/lexicons/arabic.jsonl'
AR_DIAC=re.compile(r'[\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06ed]')
